mapper.delete:
delete
from t_knowledge_repo
where knowledge_repo_id = #{knowledgeRepoId,jdbcType=VARCHAR}
  and project_id = #{project_id}

mapper.select:
select

from t_knowledge_repo
where knowledge_repo_id = #{knowledgeRepoId,jdbcType=VARCHAR}

    and project_id = #{project_id}

select

from t_knowledge_repo
where project_id = #{project_id}


        and type = #{searchCriteria.type,jdbcType=VARCHAR}


        and source = #{searchCriteria.source,jdbcType=VARCHAR}


        and knowledge_repo_id like concat('%', #{searchCriteria.id,jdbcType=VARCHAR}, '%')


        and status = #{searchCriteria.status,jdbcType=VARCHAR}


        and display_name like concat('%', #{searchCriteria.name,jdbcType=VARCHAR}, '%')


order by updated_on desc

select t1.knowledge_repo_id, t1.project_id, t1.display_name, t1., t1.type, t1.source, t1.icon, t1.icon_name, t1.size, t1.creator, t1.creator_id, t1.status, t1.metadata, t1.created_on, t1.updated_on, t2.workspace_id from t_knowledge_repo t1 left join t_knowledge_base t2 on t1.knowledge_repo_id = t2.id where t1.project_id = #{project_id} and t2.workspace_id = #{workspaceId,jdbcType=VARCHAR} and t1.knowledge_repo_id in
#{id}
(null)

mapper.update:
update t_knowledge_repo
set size     = GREATEST(size + #{changedSize}, 0),
    file_num = file_num + #{changeFileNums}
where knowledge_repo_id = #{knowledgeRepoId,jdbcType=VARCHAR}
  and project_id = #{project_id}
